/* Debrief cards for S130–S135 (+ later labs appended): root cause · fix · how to spot it in production · pattern to memorise. */
(function (root) {
  var KL = root.KL = root.KL || {}; KL.debrief = KL.debrief || {};
  var d = {
    's130-cert-user': ['Kubernetes has no user objects: identity is whatever the client certificate says (CN = user, O = groups), signed by the cluster CA.', 'Key and CSR with openssl, a CertificateSigningRequest for the client-auth signer, approve, extract the certificate, bind RBAC to the group, add a kubeconfig user and context.', 'New people cannot authenticate, or authenticate but get Forbidden; kubectl get csr shows Pending forever.', 'Key -> CSR -> object -> approve -> cert -> RBAC -> kubeconfig. Bind the group from O=, keep lifetimes short.'],
    's131-review-csrs': ['An approved CSR is permanent identity: one asking for O=system:masters would be cluster-admin for its whole lifetime.', 'Read the subject inside each request, approve only what was asked for, deny the dangerous one and leave undecided ones pending.', 'kubectl get csr lists Pending requests nobody owns; a bulk approve is a red flag in shell history.', 'Never approve what you have not decoded: base64 -d | openssl req -noout -subject.'],
    's132-leaked-cert': ['Kubernetes cannot revoke client certificates, so a stolen one stays valid until it expires; its power comes from the bindings that name its user AND its groups.', 'Delete the user-scoped and cluster-scoped bindings and replace the group binding with named users for people who still need it.', 'kubectl get rolebindings,clusterrolebindings -A -o wide | grep -i <user> and the same for each group in the certificate.', 'Cannot revoke, so remove permissions: check user bindings, group bindings and cluster bindings.'],
    's133-priorityclass-policy': ['A pod naming a PriorityClass that does not exist is rejected at admission, and a class with the default preemption policy lets a batch job evict other teams pods.', 'Create the missing class, and recreate the class with preemptionPolicy: Never: value and preemptionPolicy are immutable.', 'ReplicaSet events say no PriorityClass with name X was found; Preempted events appear on pods that were not failing.', 'Priority orders the queue; preemptionPolicy decides whether you may evict. Immutable fields mean delete and recreate.'],
    's134-context-tickets': ['Every ticket targets a context, and the namespace comes from that context; the same command in the wrong one changes the wrong environment.', 'Run kubectl config use-context first, confirm with current-context, then act without -n.', 'kubectl config current-context in your prompt; resources changed in the wrong environment.', 'Switch, confirm, act, and leave your shell on the safest context.'],
    's135-cert-group-rbac': ['A binding to kind User named auditors matches a user called auditors; the bot is user audit-bot in group auditors, so nothing matched.', 'Change the subject kind to Group (or recreate the binding), keep the role least-privilege.', 'kubectl auth can-i --as <user> --as-group <group> says no although a binding exists; kubectl get crb -o wide shows the subject kind.', 'CN is the user, O is the group: bind the kind that the certificate actually carries.']
    ,
    's136-incident-checkout': ['Four independent faults stacked behind one symptom: a missing image tag, a missing ConfigMap, a Service selector that matches nothing, and a default-deny with no allow rule.', 'Work outside in and one layer at a time: image, config reference, selector, then the allow policy; keep the default-deny.', 'Customers see timeouts; kubectl get endpoints is empty; pods show ImagePullBackOff then CreateContainerConfigError.', 'Layer your triage: pod status, pod events, endpoints, policy. Fix one, re-check, the next fault appears.'],
    's137-incident-render': ['Three independent blockers: both workers cordoned, a nodeSelector label no node carries, and a pod quota below the replica count. One cordon was deliberate and had to stay.', 'Uncordon only the healthy node, label it for the selector, raise the quota to the real need.', 'FailedScheduling events list per-reason node counts; ReplicaSet events show exceeded quota.', 'Read the whole scheduler message, and ask why before undoing someone else\'s cordon.'],
    's138-incident-release': ['A release carried three bugs: a Secret key that does not exist, a readiness probe on the wrong port and a memory limit below real usage.', 'Correct the key, the probe port and the limit; keep the probe and the limit.', 'CreateContainerConfigError, Running but 0/1 Ready, and OOMKilled with exit code 137.', 'Status names the layer: config error, probe failure, OOMKilled. Tune safeguards, never delete them.'],
    's139-incident-backend': ['Three layers failed together: a bad image tag, a Service targetPort that nothing listens on, and a restricted egress policy that also blocked DNS.', 'Fix the image, the targetPort and add a DNS egress rule while keeping the restriction.', 'wget shows bad address (DNS), timed out (policy) or connection refused (port) and each points to a different layer.', 'Error text is a map: bad address = DNS, timeout = policy, refused = port or listener.']
    ,
    's140-worked-imagepull': ['The image tag does not exist in the registry, so the kubelet cannot pull it.', 'Change only the image to a real tag and wait for the rollout.', 'ErrImagePull then ImagePullBackOff; the Events line says Failed to pull image.', 'Status, then Events, then fix one thing. The same loop solves most pod faults.'],
    's141-worked-selector': ['The Service selector matched no pod labels, so its Endpoints stayed empty.', 'Patch the Service selector to the pod label (app=mine).', 'Pods Ready, Service present, kubectl get endpoints shows <none>.', 'Compare the Service selector to the pod labels before touching either.'],
    's142-worked-configmap': ['The Deployment referenced a ConfigMap that did not exist, so the container could not be created.', 'Create the ConfigMap with the name and key the pod already expects.', 'CreateContainerConfigError, and the Event names the missing ConfigMap.', 'Satisfy the reference instead of editing the consumer; pods retry on their own.'],
    's143-yaml-tab': ['YAML does not allow tab characters for indentation; the parser stops at the first one.', 'Replace the tabs with spaces, keep the structure, apply again.', 'error parsing file: tab characters must not be used in indentation, with a line number.', 'cat -A shows tabs as ^I; set your editor to insert spaces for .yaml.'],
    's144-yaml-indent': ['Valid YAML put image under the Pod spec instead of the container, and the schema has no such field.', 'Align image under the container name.', 'error validating data: unknown field image in PodSpec.', 'Indentation is structure. The error names the object that does not own the field.'],
    's145-yaml-apiversion': ['apps/v1beta1 was removed from the API server, so the kind cannot be matched.', 'Change apiVersion to apps/v1 and apply.', 'no matches for kind Deployment in version apps/v1beta1.', 'Use kubectl api-resources and kubectl explain to get the current group and version.'],
    's146-yaml-selector': ['The Deployment selector asked for app=web but the pod template carried app=site, so the API server rejected it.', 'Make matchLabels agree with the template labels, then apply.', 'The Deployment is invalid: selector does not match template labels.', 'The selector is immutable on a live Deployment, so get it right in the file first.']
    ,
    's147-gateway-canary': ['One rule sent everything to v1, so the header and the canary share had nowhere to go.', 'Header rule first (more specific), then a rule with two weighted backends.', 'The route attached and was accepted, yet v2 never received a request.', 'Specific matches win; weights are relative. Re-apply the whole rules list, it is replaced, not merged.'],
    's148-gateway-referencegrant': ['A route may not reference a Service in another namespace unless the target namespace opts in.', 'Set the backend namespace and create a ReferenceGrant in the target namespace, naming the source and the one Service.', 'The route status says RefNotPermitted until the grant exists.', 'The grant lives with the owner of the target and should be as narrow as possible.'],
    's149-crd-schema': ['The custom resource broke three schema rules: a missing required field, a value below the minimum and a value outside the enum.', 'Fix the manifest to satisfy the CRD, do not loosen the CRD.', 'The API server lists every violated rule in one error; kubectl explain shows the schema.', 'The schema is the contract: change the object, not the contract.'],
    's150-helm-values': ['Install used a values file; a later upgrade without --reuse-values or the file would have reset replicas and service type to defaults.', 'Upgrade with --reuse-values and set only what changes.', 'helm get values shows what the release was installed with; history shows each revision.', 'Every upgrade starts from chart defaults plus the values you pass this time.'],
    's151-audit-policy': ['A catch-all RequestResponse rule logged secret bodies and everything else; rules match top-down and the first match wins.', 'Order specific rules first, log secrets at Metadata, RBAC at RequestResponse, and catch-all at Metadata; mount the policy and log path into the apiserver.', 'The audit log is huge and contains secret data; the apiserver will not start if the policy path is not mounted.', 'Log who and when for secrets, never what; and mount every path the apiserver reads or writes.'],
    's152-apparmor': ['The deprecated annotation was replaced with the securityContext field, and the profile text was written for loading on nodes.', 'Use appArmorProfile type Localhost with the profile name; write a profile that denies writes.', 'A missing Localhost profile on a node leaves the pod stuck in a blocked state.', 'Profiles must be loaded on every candidate node before the pod references them.'],
    's153-falco-rule': ['The rule matched any bash anywhere and the output was uninformative.', 'Use the spawned_process and container macros, list the shell names, add container id and command line, raise the priority.', 'Alerts for host shells drown the real container ones.', 'Prefer shipped macros over raw fields; a good alert names where and what.'],
    's154-trivy-report': ['Triage by severity and by whether a fix exists; they need different responses.', 'Extract the images with CRITICAL findings and count the fixable ones with grep, awk, sort and wc.', 'Four images, three with a CRITICAL; six of seven findings have a fix.', 'Fixable findings mean rebuild or bump; unfixable ones need mitigation or a different base image.'],
    's155-version-skew': ['Three components were outside the supported skew: an old scheduler and two kubelets, one too old and one newer than the apiserver.', 'Compare each minor version with the apiserver minor using the policy table.', 'kubelet newer than apiserver is never supported; scheduler and controller-manager may be one minor behind at most.', 'Upgrade the control plane first, then nodes; never let a node component run ahead.'],
    's156-ephemeral-debug': ["An ephemeral container was added to the running pod without restarting it, so you could inspect a shell-less image.", "`kubectl debug -it POD --image=... --target=CONTAINER` attaches a container that shares the target's process namespace; `-c` names it.", "Ephemeral containers cannot be removed or edited, never restart, and are not in the pod template: they are for debugging only.", "Reach for `--copy-to` (S157) when changing the command or image is acceptable; use an ephemeral container when the live pod must not be touched."],
    's157-debug-copy': ["The Deployment's own command exited with code 3 (a leftover maintenance command), which made every pod crash.", "`kubectl debug POD --copy-to=NAME --container=APP -- sleep 3600` clones a pod and replaces the crashing command so you can look around.", "The copy has no labels, so no Service sends it traffic; but it does hold resources, so delete it when done.", "Fix the controller, not the pod: pods owned by a Deployment are recreated from the template."],
    's158-vap-binding': ["A ValidatingAdmissionPolicy does nothing until a ValidatingAdmissionPolicyBinding activates it; the binding sets the action (Deny/Warn/Audit) and the scope.", "Scope with `matchResources.namespaceSelector` so a Deny cannot lock out namespaces you did not mean to govern.", "Three probes prove the behaviour: bad image rejected where bound, good image accepted, other namespace untouched.", "CEL expressions use `object`, `oldObject`, `request` and `params`; test a policy with Warn or Audit first in real clusters."],
    's159-vap-rejected': ["The deployment was rejected by three different policy rules, one at a time: replicas, the owner label and the registry.", "Read the denial message: it names the policy, the binding and the failed rule.", "Fix the manifest to comply; never delete a binding you do not own to get past a policy.", "`kubectl explain` and the policy YAML tell you the rules; ask the policy owner for an exception instead of working around it."],
    's160-pvc-expand': ["A bound claim can only be grown, and only when its StorageClass has `allowVolumeExpansion: true`.", "Patch the StorageClass first, then raise `spec.resources.requests.storage`; the controller updates the capacity, usually without restarting the pod.", "Shrinking is refused by the API; deleting and recreating a claim to resize it loses data when the reclaim policy is Delete.", "Back up before you resize anything that holds data."],
    's161-immutable-config': ["An immutable ConfigMap cannot be edited, only deleted and recreated; that is its purpose.", "Roll out a new value with a new, versioned object (`-v2`) and repoint the Deployment; the pod template changes, so pods roll.", "Rollback is just pointing back at v1, which still exists exactly as it was.", "`immutable: true` also reduces load on the API server because kubelets stop watching it."],
    's162-projected-volume': ["A projected volume merges a ConfigMap, a Secret and Downward API files into one directory.", "Two volumes cannot share a mountPath; `projected.sources` is the tool for that.", "`kubectl explain pod.spec.volumes.projected.sources --recursive` shows every source type.", "File names must be unique across the sources, or the pod will not start."],
    's163-native-sidecar': ["A native sidecar is an init container with `restartPolicy: Always`: it starts before the app, stays running and is restarted if it exits.", "Moving a long-running container into `initContainers` without that field blocks the pod forever.", "Sidecars start in order and stop after the app containers, which keeps logs flowing until the end.", "Use it for log shippers, proxies and agents; use regular init containers for one-time setup."],
    's164-netpol-iprange': ["One `ports` entry with `port` and `endPort` allows a whole range; 8090 stayed blocked because it is outside it.", "`ipBlock` matches IP addresses, `from` entries are ORed, and selectors in the same entry are ANDed.", "Keep the default-deny policy: you add allow rules next to it.", "Test from the client for an allowed port and a blocked port; allowed-only testing hides over-broad rules."],
    's165-inplace-resize': ["Pod resources change only through the `resize` subresource, and the running container picks up the new size without a restart.", "Requests and limits moved together so the QoS class stayed Guaranteed; a change of QoS class is refused.", "`resizePolicy` per container says whether a restart is needed (NotRequired for CPU, often RestartContainer for memory).", "A request larger than any node can offer leaves the resize Pending/Infeasible while the container keeps running at its old size."],
    's166-user-namespace': ["`hostUsers: false` runs the pod in its own user namespace: root inside maps to an unprivileged user on the node.", "It needs runtime and kernel support and cannot be combined with hostNetwork, hostPID, hostIPC or host path volumes.", "This is a better answer than `runAsNonRoot` when the image truly needs UID 0.", "It limits the damage of a container escape; it does not replace seccomp, capabilities or RBAC."],
    's167-explain-lookup': ["Field names, enum values and types come from `kubectl explain`, which is available in the exam without opening a browser.", "Walk the path with dots; add `--recursive` for the tree.", "The first value listed in an enum is not necessarily the default; read the description.", "Copy exact names: the API is case-sensitive and rejects typos."],
    's168-explain-required': ["`-required-` in explain output marks fields you must set inside that object.", "Enum values and field names for rarely-used objects are exactly what you cannot remember: look them up.", "A list element's required fields are required per element, not for the list.", "Known gaps in the simulator's explain are marked: for anything it does not list, use kubernetes.io/docs/reference."],
    's169-build-from-explain': ["The constraint lives under the POD spec, as a list: maxSkew, topologyKey, whenUnsatisfiable and a labelSelector.", "`whenUnsatisfiable` has no default and is required: DoNotSchedule keeps pods Pending, ScheduleAnyway only prefers balance.", "The labelSelector must match the pods you want to spread, otherwise the constraint counts nothing.", "Build the YAML from `kubectl explain --recursive`, then `kubectl patch` or edit; do not copy from memory."],
    's170-capstone-cka': ["Triage first: `get all,pvc,netpol,quota` shows most of the nine faults in one pass, so you can fix the cheap ones before the hard ones.", "Several faults hide behind each other: labelling the node fixes scheduling, but only the quota arithmetic tells you whether 3 replicas fit.", "A PVC's storageClassName is immutable: the fix is delete and recreate, which is only safe because the claim holds no data yet.", "Partial credit is real on the exam: bank the quick wins (selector, CronJob, PDB, RBAC) before spending ten minutes on one hard task."],
    's171-capstone-ckad': ["A pod stops at the first configuration error it hits: image, then ConfigMap key, then Secret key, then probe. Re-read describe after every fix.", "A Job's pod template is immutable: a failed Job is deleted and recreated, not edited.", "An HPA needs CPU requests on the target pods, which is why the constraint protects them.", "Create the cheap objects (HPA, Ingress, CronJob patch) with imperative commands: `kubectl autoscale`, `kubectl create ingress`."],
    's172-capstone-cks': ["Order matters: fix the pod security context before enforcing `restricted`, or the new pods are refused.", "Hardening is layered: pod security, least-privilege RBAC, network policy, secret handling and admission policy each close a different hole.", "A Secret mounted as a read-only volume does not leak through `env` or `kubectl describe`, and it can be rotated without a restart.", "Test the negative case: the policy only counts if `intruder` is actually blocked and the unpinned image is actually denied."],
    's173-scheduler-down': ['Pods stay Pending with an empty Events section because nothing ever tried to place them: the kube-scheduler static pod was crash-looping on an unknown flag (--bind-adress).', 'Read the scheduler\'s logs, correct the flag name in /etc/kubernetes/manifests/kube-scheduler.yaml, and let the kubelet recreate the static pod; the Pending pods are then scheduled by themselves.', 'Pending with NO FailedScheduling event is the signature of a missing or broken scheduler; Pending with a FailedScheduling event means the scheduler ran and found no fit.', 'Control-plane component down: check kubectl get pods -n kube-system, then logs, then the manifest; events tell you who acted, so no events means nobody did.'],
    's174-controller-manager': ['The Deployment controller lives in kube-controller-manager, which exited because --cluster-signing-key-file pointed at a file that does not exist (ca.keyy), so no ReplicaSet was ever created.', 'Read the controller manager\'s logs, correct the path in its static pod manifest and wait for the kubelet to restart it; the Deployment then gets a ReplicaSet and pods.', 'A Deployment with no ReplicaSet (kubectl get rs is empty) while existing pods keep running points at the controller manager, not the scheduler or the kubelet.', 'Objects that never get their children (ReplicaSets, pods, Endpoints, Job pods) mean a controller is down: look at kube-controller-manager first.'],
    's175-apiserver-etcd': ['kube-apiserver exited because --etcd-servers pointed at port 2381 while etcd listens on 2379, so it could not create its storage backend and every kubectl call was refused.', 'With kubectl unusable, use crictl ps -a and crictl logs on the node to read the Exited container, compare --etcd-servers with etcd\'s --listen-client-urls, fix the manifest and let the kubelet restart the pod.', 'Connection refused on port 6443 from kubectl means the API server is not listening; crictl shows whether the container exited and its logs say why.', 'When the API server is down, kubectl is useless: fall back to crictl, the kubelet journal and the static pod manifests, and always keep a copy of the file you edit.'],
    's176-kube-proxy-mode': ['kube-proxy refuses to start with an unknown mode (ipvss) in its ConfigMap, so every DaemonSet pod crash-loops and Service rules stop being programmed on new nodes.', 'Fix mode to iptables or ipvs in the kube-proxy ConfigMap, then kubectl rollout restart ds/kube-proxy so the pods re-read it.', 'CrashLoopBackOff on kube-proxy pods with an error naming the proxy mode or clusterCIDR in their logs points at the ConfigMap, not the image.', 'A DaemonSet that reads its config at start needs a restart after the ConfigMap changes; mounted ConfigMaps update on disk but the process does not re-read them.'],
    's177-cni-missing': ['The runtime found no valid file ending in .conf, .conflist or .json in /etc/cni/net.d (the config had been renamed to .disabled), so no pod sandbox could get a network and pods stayed in ContainerCreating.', 'Restore the config under its real name so it is a valid CNI file; the kubelet retries the sandbox and the pods start without being touched.', 'ContainerCreating plus a FailedCreatePodSandBox event that says no valid networks found in /etc/cni/net.d is a node-level CNI problem, not a workload problem.', 'Every new pod stuck at the sandbox step, on one node or all, means look at the CNI config and the CNI plugin pods before you touch the Deployment.'],
    's181-etcd-nospace': ['etcd reached its storage quota and raised a NOSPACE alarm, so it rejects every write with database space exceeded while reads still work.', 'Compact old revisions up to the current one, defragment to give the space back, then disarm the alarm; disarming first is refused or comes straight back.', 'Writes failing with etcdserver: mvcc: database space exceeded while reads succeed, and etcdctl alarm list showing NOSPACE, is the signature.', 'The order is compact, defrag, disarm; deleting data files under the etcd data directory corrupts the member and is never part of the fix.'],
    's178-join-token-expired': ['The saved kubeadm join command carries a bootstrap token that expired (24h default), so the API server no longer accepts it for discovery or TLS bootstrap.', 'Create a new token on the control plane with kubeadm token create --print-join-command and run the printed command on the node; the node joins and its pods are rescheduled.', 'An error saying the token id is invalid or has expired during the preflight or discovery phase of kubeadm join is the signature, not a network or certificate problem.', 'Bootstrap tokens are short-lived credentials: always mint a fresh one rather than reusing a command from notes or chat.'],
    's179-metrics-server': ['kubectl top and the HPA depend on the Metrics API served by metrics-server; its Deployment used an image tag that does not exist, so with a Recreate strategy no pod was left serving.', 'Correct the image tag with kubectl set image, wait for the rollout, then kubectl top works again; do not disable kubelet TLS verification as a shortcut.', 'error: Metrics API not available from kubectl top, and HPA targets showing unknown, point at metrics-server not being Ready in kube-system.', 'No metrics means check the metrics-server Deployment and its APIService before suspecting the workloads that are being measured.'],
    's180-no-default-sc': ['A PVC with no storageClassName is only dynamically provisioned when exactly one StorageClass is marked default; the default annotation had been removed, so the claim waited with no storage class set.', 'Annotate the intended class with storageclass.kubernetes.io/is-default-class=true; the binder then provisions the claim without editing it.', 'kubectl get sc with no (default) marker, and a Pending claim whose event says no storage class is set, is the signature.', 'Dynamic provisioning needs a class from the claim or from the cluster default: if a claim has none and no default exists, it waits forever.'],
    's182-multi-logs': ['The failing container was sync, not web: it tried to reach the cache on port 6397 (a typo for 6379) and exited, so the pod showed 1/2 and restarted while web kept serving.', 'Name the container with -c, read the crashed run with --previous, then correct the port in the Deployment template so the new pods start clean.', 'READY 1/2 with restarts means one container of several is failing; kubectl logs without -c picks a default or asks you to choose, and --previous is the only way to read the run that just died.', 'In a multi-container pod always pick the container (-c), and use --previous for crash loops: the evidence disappears with the next restart.'],
    's183-events-triage': ['The shop pods could not start because the ConfigMap shop-config they mount does not exist; the other warnings in the namespace belong to unrelated workloads.', 'Filter events to the pod you were asked about, read the missing object in the FailedMount message, create it, and leave the other teams\' workloads untouched.', 'A namespace-wide events list mixes many problems: --for, --field-selector involvedObject.name and --types=Warning narrow it to the object and severity that matter.', 'Triage by object first, then by reason; the loudest warning is rarely the one attached to your ticket.'],
    's184-removed-apis': ['The manifests use API versions that were removed (extensions/v1beta1, networking.k8s.io/v1beta1, batch/v1beta1), so the API server has no such resource to create.', 'Move each object to its current group and version and fix the fields that changed: apps/v1 needs spec.selector, networking.k8s.io/v1 needs pathType and backend.service, batch/v1 CronJob is otherwise unchanged.', 'The error says no matches for kind in version: the kind exists, the version does not. kubectl api-resources and kubectl explain show what the cluster serves today.', 'Changing only apiVersion is a half fix: removed versions usually changed their schema too, so validate with a real apply.'],
    's185-labels-at-scale': ['Labels and annotations are metadata used by selectors; changing many objects safely means selecting them with -l rather than naming each one or using --all.', 'kubectl label -l env=prod team=payments adds, key- removes, and kubectl annotate does the same for annotations; the dev pods are outside the selector and stay untouched.', 'Preview the target set with kubectl get pods -l env=prod --show-labels before you change anything, and compare the counts after.', 'A selector is the unit of bulk change: write it first, check what it matches, and only then run the mutating command.'],
    's186-named-port': ['The Service targeted the port by the name http, but the container declares its port as web, so the name resolved to nothing and no pod qualified as an endpoint.', 'Change the Service targetPort to the declared name web (or use the number); the endpoints appear without restarting any pod.', 'Pods Running and Ready, selector correct, endpoints empty: compare the Service targetPort with the pod\'s containerPort names and numbers.', 'A named targetPort is resolved per pod against the container ports: a mismatch looks like a selector problem but is a port problem.'],
    's187-adapter-sidecar': ['The adapter pattern adds a sidecar that reads what the main container writes and re-exposes it in the format the platform expects; it only works if both containers mount the same volume.', 'Add the exporter container to the pod template with the shared emptyDir mounted read-only and a command that keeps running, leaving the app container unchanged.', 'Two containers in one pod sharing a volume, one of them read-only and tailing a file, is the shape of an adapter or log-shipper sidecar.', 'Sidecars share the pod\'s network and volumes, not its filesystem: share data through a volume, and mount it read-only when the sidecar only needs to read.'],
    's188-kustomize-overlay': ['An overlay layers environment-specific changes on a shared base: prefix, replicas, image, a patch and a generated ConfigMap, without editing the base files.', 'Create the overlay kustomization.yaml, preview it with kubectl kustomize, then apply it with -k; the generator adds a content hash to the ConfigMap name and rewrites the references to it.', 'kubectl kustomize prints exactly what -k would apply; compare names, replicas, images and the generated ConfigMap reference before you apply.', 'Base plus overlays: keep the base environment-neutral, put differences in the overlay, and always read the rendered output.'],
    's189-helm-reuse-values': ['helm upgrade resets every value not supplied again to the chart defaults, so a plain upgrade to change one value would drop replicaCount to 1 and revert the Service type.', 'Upgrade with --reuse-values and set only image.tag, or pass the full values file; helm get values shows what the release currently holds.', 'helm get values before and after an upgrade, and helm history, show whether the user-supplied values survived the new revision.', 'Treat an upgrade like a deploy of the whole release: either carry the old values forward explicitly or keep them in a values file under version control.'],
    's190-kubelet-hardening': ['The kubelet API on every node accepted anonymous callers, authorized everything (AlwaysAllow) and exposed an unauthenticated read-only port, so anyone on the network could list pods or run commands on the node.', 'Set anonymous.enabled false, webhook authentication true, authorization.mode Webhook and readOnlyPort 0 in /var/lib/kubelet/config.yaml, keep the client CA, then restart the kubelet.', 'kube-bench items 4.2.1 to 4.2.4 flag these settings; reading the kubelet config file (or the running flags) shows them directly.', 'The kubelet is an API server on every node: require authentication, delegate authorization to the API server, and close the extra ports.'],
    's191-bench-permissions': ['kube-bench flagged control-plane files that were readable by group and others, and an etcd data directory not owned by the etcd user; these files hold credentials and the cluster state.', 'Restrict exactly the named files to 600 and set the etcd data directory to etcd:etcd, keeping content unchanged, then re-run the benchmark.', 'stat -c with %a and %U:%G, or ls -l, prints the mode and owner that each kube-bench item checks.', 'Fix what the finding names with the smallest change: tightening is chmod 600 on files, chown for ownership, and never 777 or a recursive chmod of a parent directory.'],
    's192-registry-policy': ['Nothing stopped pods from running images pulled from any registry; a ValidatingAdmissionPolicy with a CEL rule and a Deny binding enforces the allowed prefix at admission.', 'Create the policy (matchConstraints on pods, CEL startsWith on every container image) and a binding with validationActions Deny and a namespace selector, then test a compliant and a violating pod.', 'A rejected create says denied request by ValidatingAdmissionPolicy with the policy message; a policy with no binding, or with Audit only, rejects nothing.', 'Policy plus binding: the policy states the rule, the binding scopes and enforces it; always test both outcomes before relying on it.'],
    's193-seccomp-localhost': ['A Localhost seccomp profile is read by the kubelet from /var/lib/kubelet/seccomp on the node; the file was never installed there, so the container could not be created.', 'Copy the profile to the path the pod names under the kubelet seccomp directory; the kubelet retries and the pod starts with the profile enforced.', 'CreateContainerConfigError with a message about loading a seccomp profile and a missing path under /var/lib/kubelet/seccomp is the signature.', 'localhostProfile is relative to the kubelet seccomp directory on whichever node runs the pod: the file must exist on every node it can land on.'],
    's194-apparmor-load': ['A Localhost AppArmor profile must already be loaded in the node\'s kernel; the profile existed only as a file, so the pod could not be started with it.', 'Load the profile with apparmor_parser -r, confirm it with aa-status, and the pod starts with the profile attached; do not remove the field to get it running.', 'The container does not start and the message says the AppArmor profile is not loaded; aa-status shows it missing from the loaded list.', 'Profiles are per node and per boot: load them on every node (and at boot) before any pod references them.'],
    's195-falco-shadow': ['The rule matched every read under /etc at INFO priority, so it produced noise and hid the one event that matters: a container process reading the password hash files.', 'Condition open_read and container and fd.name in (/etc/shadow, /etc/gshadow), an output naming container, process and user, and priority WARNING or higher.', 'In Falco output a flood of low-priority alerts from one rule means its condition is too broad; tighten file names, add the container macro and raise the priority.', 'A good rule is narrow in what it matches and rich in what it reports: exact file, container scope, who and what did it.'],
    's196-falco-outbound': ['The rule matched every connect event on the host at DEBUG, which is every connection of every process, so nothing could be acted on.', 'Condition outbound and container and not in the cluster or loopback ranges, with container, process and destination in the output, and priority NOTICE or higher.', 'Alerts that fire constantly and name no container point at a condition missing the container macro and a destination filter.', 'Detect the exception, not the norm: scope to containers, exclude the known-good destinations, and report enough fields to start an investigation.'],
    's197-secret-in-configmap': ['A password in a ConfigMap is readable by anyone who can read the namespace and is usually committed to git; the real mistake is storing a credential in a non-secret object.', 'Remove it from the ConfigMap, create a Secret with a new rotated value, and reference it with secretKeyRef, leaving the harmless settings in the ConfigMap.', 'kubectl get cm -o yaml shows the plaintext value; grep for password, token and key in ConfigMaps and manifests finds these.', 'Treat a leaked value as compromised: move it to a Secret and rotate it, then restrict who can read secrets and encrypt them at rest.'],
    's198-topology-spread': ["The spread constraint allows at most one pod of difference between zones. Zone b had no free CPU because of the batch job, so after the first pod landed in zone a the next one would have made the skew 2, and no zone could take it: three pods stayed Pending.", "Relax whenUnsatisfiable to ScheduleAnyway (or raise maxSkew) so the spread is still preferred but no longer blocks scheduling, keeping the constraint on the pod template.", "The scheduler message names the topology spread constraints next to the zone that cannot take the pod; compare the pod count per zone and the free capacity of each zone.", "A DoNotSchedule constraint trades availability for balance: size the zones for it, or choose ScheduleAnyway when a balanced layout is a preference rather than a rule."],
    's199-pv-node-affinity': ["The local volume was tied by its node affinity to a hostname that does not exist, so no node could satisfy the volume and the pod stayed Pending with a volume node affinity conflict.", "Delete the pod, claim and volume, correct the hostname in the PV manifest to the node that holds the disk, and apply the PV, the claim and the pod again in that order.", "describe pod shows the volume node affinity conflict, and the PV spec shows the hostname it demands; kubectl get nodes shows the real names.", "A local PersistentVolume pins data to one node by design: the pod follows the disk, so a wrong or stale hostname strands the workload."],
    's200-hostport-conflict': ["Each replica asked for host port 8080, and a node can give that port to only one pod, so with two workers only two replicas could be scheduled and the other two stayed Pending.", "Remove the hostPort and publish the app through a NodePort Service, which spreads traffic across all replicas without reserving a port on each node.", "The Pending pods' events say a node did not have free ports for the requested pod ports; count the nodes against the replicas.", "hostPort limits a Deployment to one pod per node and complicates rolling updates; a Service gives stable access without that constraint."],
    's201-requests-above-limits': ["The manifest asked for 500m CPU but limited the container to 250m, and a request above its own limit can never be honoured, so the API server refused the object.", "Lower the request or raise the limit so the request is not above the limit, keep both values, and apply the file again.", "The error names the exact field path, spec.template.spec.containers[0].resources.requests, and both values.", "The request is what the scheduler reserves and the limit is the ceiling at run time; the request must never exceed the limit."],
    's202-pull-policy-never': ["imagePullPolicy Never tells the kubelet to use only an image already on the node, and reporter:2.0 was not preloaded, so the container could not start and reported ErrImageNeverPull.", "Change the pull policy to IfNotPresent (or Always) so the node pulls the image from the registry, keeping the same image and tag.", "The pod status and the Failed event show ErrImageNeverPull and a message saying the image is not present with a pull policy of Never.", "Never is for images you load onto each node yourself, for example in a local cluster; registry images need IfNotPresent or Always."],
    's203-downward-api': ["The fieldPath spec.nodename is not a supported Downward API field (the correct name is spec.nodeName), so the API server refused the pod.", "Correct the field path, apply the file, and read NODE_NAME and POD_IP from inside the running container to confirm they resolve.", "The error lists every supported field path; kubectl exec with printenv shows the values the container really received.", "Downward API values are set when the container starts: a wrong path fails at creation, and a changed path needs a new pod."],
    's204-job-suspended': ["The Job had spec.suspend set to true, so its controller created no pod at all; nothing was wrong with the image or command.", "Patch spec.suspend to false: the Job then creates its pod and completes, and keeps its name and history.", "describe job and its conditions show the Job as suspended, and kubectl get jobs lists it with the status Suspended.", "suspend lets a controller or a person hold a Job and release it later; deleting and re-creating would also run it but lose its history."],
    's205-readonly-rootfs': ["The container's root filesystem was read-only, and nginx must write its cache and pid file, so it exited at start with a read-only file system error and the pod went into CrashLoopBackOff.", "Keep readOnlyRootFilesystem true and mount writable emptyDir volumes at exactly the paths nginx writes, /var/cache/nginx and /var/run.", "The container log names the path that failed with Read-only file system; kubectl logs --previous keeps the crashed run.", "A read-only root filesystem blocks tampering with the image's files; the process still needs a few writable directories, given as volumes rather than by loosening the setting."],
    's206-immutable-selector': ["A workload's spec.selector cannot be changed after creation, so applying a definition with an extra selector label was refused.", "Delete the Deployment (orphaning its pods keeps the Service serving), apply the new definition with the new selector, then remove the orphaned old pods once the new ones are Ready.", "The error says the selector field is immutable and prints the selector you tried to apply; kubectl get ep shows whether the Service kept endpoints during the change.", "Choose selector labels carefully at creation: changing them later means re-creating the controller, and the pods it owned are matched by the old selector."],
    's207-pod-immutable': ["A running Pod only accepts changes to a few fields, such as the image, so the new CPU limit in the manifest was refused with a message listing what may change.", "Replace the Pod from the file with kubectl replace --force (or delete it and apply again), keeping the name; for a Deployment edit the Deployment instead.", "The refusal names the allowed fields (images, activeDeadlineSeconds, tolerations, terminationGracePeriodSeconds), so resources are outside it.", "Bare Pods are replaced, not edited; controllers such as a Deployment roll out a new pod from an edited template for you."],
    's208-sts-parallel': ["With the default OrderedReady policy a StatefulSet creates pod N+1 only after pod N is Running and Ready, so one pod stuck on a bad image kept cache-1 and cache-2 from ever being created.", "Fix the image in the manifest, delete the StatefulSet with --cascade=orphan so pods and claims stay, then apply the file with podManagementPolicy: Parallel.", "podManagementPolicy is immutable on a live StatefulSet; the refusal says only replicas, template and a few other fields may change, which is why the object is re-created.", "Parallel suits independent replicas; keep OrderedReady where members must join a cluster in order, and never delete the claims because they hold the data."],
    's209-svc-traffic-policy': ["externalTrafficPolicy is only valid on NodePort and LoadBalancer Services, so the file was refused while the type was ClusterIP.", "Set type NodePort with nodePort 30090, keep externalTrafficPolicy Local to preserve the client IP, and use sessionAffinity ClientIP with timeoutSeconds 3600 for one-hour stickiness.", "The validation message names the field and says it may only be set for externally-accessible services, so the type is what to change.", "Local also means a node without a local ready pod drops that traffic, and sessionAffinityConfig is only accepted together with ClientIP affinity."],
    's210-image-digest': ["The api reference had 62 hex characters instead of 64, so the image name could not be parsed and the pods stayed in InvalidImageName; no pull was even attempted.", "Copy the full reference from the approved list with kubectl set image, for both api and worker, so each Deployment is pinned to its digest.", "The event says invalid reference format, which points at the name itself rather than at the registry or credentials.", "A digest names exact content, a tag can move; pin by digest and keep the readable tag in a comment or label for people."],
    's211-ndots-dnsconfig': ["With ndots:5 a name with fewer than five dots is tried under each search domain first, so api.partner.example.com cost several failed queries before the real one.", "Add dnsConfig options ndots=1 to the pod template and keep dnsPolicy ClusterFirst, so Service names still resolve through the cluster DNS server.", "resolv.conf in the pod shows the search list, the nameserver and the ndots option, and the rollout replaces the pods so the new file appears.", "dnsPolicy None would drop the cluster nameserver unless you list it yourself; a trailing dot on the name is the application-side alternative."],
    's212-rbac-bind': ["The API server refuses to let a user create a binding or role that grants permissions the user does not hold, so team-lead could not bind view even with create on rolebindings.", "The exception is the bind verb on that specific role: a rule on clusterroles with verb bind and resourceNames view lets the lead hand out view and nothing else, while escalate or a wildcard would allow anything.", "The refusal lists the permissions not currently held, which tells you the check is about the role being granted rather than about creating bindings.", "Holding bind on one named role does not allow binding admin, and the same rule on roles (not clusterroles) would cover namespaced Roles."],
    's213-sts-canary': ["A StatefulSet updates pods from the highest ordinal down, and updateStrategy.rollingUpdate.partition is the first ordinal that is updated, so partition 3 with four pods updates only web-3.", "Patch the partition and the image together so no other pod starts updating, then confirm with rollout status and the pod images.", "rollout status says the partitioned roll out is complete once the pods at or above the partition are updated and Ready.", "Pods below the partition keep, and when deleted are recreated with, the old revision, so the canary stays a canary until the partition is lowered."],
    's214-sts-finish-rollout': ["Partitioned roll out complete only means the pods at or above the partition are updated: queue-0 to queue-2 were never meant to change until the partition moves.", "Lower rollingUpdate.partition to 0 and the controller replaces the remaining pods from the highest ordinal down, one at a time.", "Deleting an old pod by hand does not help: below the partition it is recreated from the old revision.", "kubectl rollout status then reports a full rolling update and updatedReplicas equals the replica count."],
    's215-admin-cert-renew': ["Only the admin client certificate had expired, shown as invalid in kubeadm certs check-expiration, so the API server and the pods kept working while every kubectl call from the workstation was unauthorized.", "Renew just admin.conf on cp1, then copy the new /etc/kubernetes/admin.conf over the workstation kubeconfig; renewing on the node alone does not change the copy kubectl reads.", "Copying the file before the renewal brings the expired certificate back, which is why the order matters.", "Renewing all certificates and restarting the control plane would have worked but touches components that were not expiring, and kubeadm does not renew the certificate authorities."],
    's216-gameday-three': ["Three unrelated faults: web used an image tag that does not exist, the api Service forwarded to port 8080 while the pods listen on 80, and worker asked for the ConfigMap key mode while the key is spelled Mode.", "Read pods and events first, then take each symptom to its own cause: ImagePullBackOff to the tag, a Ready Deployment with failing requests to the Service targetPort, CreateContainerConfigError to the missing key.", "Each fault shows up in a different place, so one fix does not change the others and none of them needed the namespace recreated.", "Fix the smallest thing that is wrong, in the object that owns it, and verify each workload separately."],
    's217-netpol-and-or': ["Inside one from list item, namespaceSelector and podSelector are ANDed: the peer must be in the namespace and carry the label. As two separate items they are ORed, so every pod in ops and every backup-labelled pod in vault was admitted.", "Rewrite the policy with both selectors in the same item, then test from backup, scratch and rogue instead of trusting the YAML.", "A podSelector on its own only matches pods in the policy's own namespace, which is how rogue got in.", "Policies are additive and cannot subtract, so the fix is to narrow the allow rule itself, not to add another policy."],
    's218-missing-sa-view': ["The Deployment named a ServiceAccount that did not exist, so the ReplicaSet could not create any pod and the error appears in ReplicaSet events, not on a pod.", "Create the account, then give it the built-in view ClusterRole through a RoleBinding in this namespace so it can read, not change, objects there.", "A RoleBinding that references a ClusterRole grants it only inside the binding's namespace, which is why listing pods in default stays denied.", "Verify with kubectl auth can-i --as system:serviceaccount:<ns>:<name> for an allowed and a denied case."],
    's219-runasnonroot': ["runAsNonRoot makes the kubelet refuse to start a container whose image would run as UID 0, which shows as CreateContainerConfigError on the pod.", "Keep the control and give the pod a numeric runAsUser, because the kubelet cannot prove that a named user is not root.", "Drop all capabilities at container level as well, and add back only what the app needs.", "Read the event first: it names the exact check that failed."],
    's220-ingress-pathtype-port': ["Exact matches only the path /api itself, so /api/v1/orders found no rule; Prefix matches the path and everything below it, split on slashes.", "The web backend named port 8080 while the Service exposes 80, so the controller had no upstream and answered 503.", "Compare the Ingress backends with kubectl get svc before choosing a port, and edit the Ingress in place.", "A catch-all or wildcard would stop the errors and send traffic to places nobody intended."],
    's221-inventory-report': ["custom-columns builds the NAME and IMAGE table from JSONPath expressions, so the file stays right when pods change.", "--sort-by with metadata.creationTimestamp orders the list and -o name prints one pod/<name> per line.", "jsonpath {.spec.nodeName} on one named pod prints just the node, with no newline or extra text.", "Generate the files with kubectl output options instead of copying values by hand."],
    's222-audit-rule-order': ["The API server uses the first audit rule that matches a request. The draft began with a rule that had no selectors, so every request matched it and the specific rules below never ran.", "Put the specific rules first and the catch-all last: events at None, pods/exec at RequestResponse, Secrets at Metadata, everything else at Metadata.", "Secrets stay at Metadata. At Request or RequestResponse the secret values would be written to the audit log in clear text.", "Order is part of the policy, so read it top to bottom whenever a rule seems to have no effect."],
    's223-kubelet-hardening': ["Anonymous authentication let unauthenticated callers reach the kubelet API, AlwaysAllow authorised every caller, and the read-only port served pod data with no authentication at all.", "Set anonymous.enabled to false, authorization.mode to Webhook so the kubelet asks the API server, and readOnlyPort to 0.", "Leave the client CA path and the rest of the file alone: a hardening change should be the smallest one that fixes the finding.", "On a real node, restart the kubelet after editing its config and check the node returns to Ready."],
    's224-helm-drift': ["kubectl scale changed the Deployment but not the release, so Helm still recorded 2 replicas and would reset the change on the next upgrade.", "Change the value through Helm so the release records it and keeps a history: helm upgrade with --reuse-values and --set replicaCount=3.", "--reuse-values keeps the other settings, here image.tag=1.26. Without it every value you did not pass falls back to the chart default.", "helm get values shows what the release believes; kubectl shows what is running. A difference between them is drift."],
    's225-kustomize-patch-target': ["A strategic-merge patch finds its target by group, kind and name. The patch named web, the base Deployment is webapp, so nothing matched and Kustomize raised no error.", "Fix the name in the overlay, not the base, then compare kubectl kustomize output before applying.", "When an overlay seems to do nothing, check names, kinds and namespaces in the patch against the base first.", "kubectl apply -k builds the overlay and applies the result in one step."],
    's226-ingress-to-gateway': ["The Ingress rules map onto two objects: a Gateway holds the listener, and an HTTPRoute holds hostnames, matches and backends and attaches through parentRefs.", "The host moves from the Ingress rule to the route hostnames, and each Ingress path becomes a rule with a PathPrefix match.", "Create the Gateway and route and check them before removing the Ingress, so traffic is never left without a path.", "A route that names a Gateway that does not exist attaches to nothing, so check parentRefs first when a route does not work."],
    's227-gameday-five': ["Five unrelated faults, five different layers: a policy selecting the frontend pods and allowing nothing, a Service selector that matches no pod, a memory request no node can satisfy, a Secret that does not exist, and an image tag that does not exist.", "Each one left its own evidence: a policy in kubectl get netpol, empty endpoints, a Pending pod with a scheduling event, CreateContainerConfigError, and ImagePullBackOff.", "Sort by symptom first: pods that do not run (events), pods that run but are unreachable (endpoints, then policy), and fix them one at a time, testing after each.", "Keep the NetworkPolicy and add the one allowed path instead of deleting the policy."],
    's228-gameday-cks': ["Restricted Pod Security rejected books for several missing securityContext settings at once; the ReplicaSet event lists all of them, so fix the pod spec instead of lowering the namespace level.", "A RoleBinding gave the default ServiceAccount the admin ClusterRole, so every pod in the namespace could administer it; deleting that one binding removes the grant.", "An empty podSelector with policyTypes Ingress and no rules denies ingress to every pod until a rule allows it.", "nginx:latest moves over time; an exact tag makes the running image reproducible and reviewable."],
    's229-pending-three-causes': ["Three pods with the same Pending status and three causes: a node selector no node satisfies, a memory request above any node, and a volume claim naming a StorageClass that does not exist.", "Each cause is written in that pod's own Events, and the scheduler states it in different words: node selector, Insufficient memory, unbound PersistentVolumeClaim.", "Run describe on each pod separately and read the message before changing anything; then fix the field it names, once per workload.", "A claim's StorageClass cannot be edited, so recreate the claim under the same name with the default class; do not delete the Deployments."],
    's230-crashloop-three-causes': ["CrashLoopBackOff only says the container keeps ending. Here a liveness probe on a path nginx does not serve, a memory limit below what the program needs, and a command that exits by itself each produced it.", "The evidence differs: Liveness probe failed in Events, Last State OOMKilled, and exit code 3 with one line of log output.", "Read Last State, the Events and the logs before choosing a fix; exit code 137 alone does not tell the OOM killer from a probe kill.", "Fix the probe path, the limit and the command separately, and confirm each pod is Ready."],
    's231-noendpoints-three-causes': ["Three Services that answer nothing: a selector with a typo, a targetPort nothing listens on, and a pod left out of the Endpoints because its readiness probe fails.", "Endpoints tell them apart: empty for the selector and for the unready pod, populated but unreachable for the wrong port.", "Check kubectl get endpoints first, then compare selector with pod labels, then the port, then pod readiness.", "Change the one wrong field in each object; the Deployments and Services stay."],
    's232-configerror-three-causes': ["Three pods in CreateContainerConfigError: a ConfigMap that does not exist, a Secret without the requested key, and a ConfigMap key spelled in a different case.", "The Events name the object and the key, so the cause is readable: not found versus couldn't find key.", "Add the missing object, add the missing key, or correct the reference, whichever matches what the workload is meant to receive.", "Keys are case sensitive; do not remove the valueFrom to make the error go away."],
    's233-noisy-namespace': ["The outage was one Service sending traffic to a port nothing listens on. The suspended CronJob, the finished Job and the Pending GPU pod were all intentional.", "Starting from the symptom (endpoints of checkout) avoids chasing the noise in the Events.", "A suspended CronJob, a Completed Job and an unschedulable pod that waits for hardware are normal states, not faults.", "Changing them risks running an export, repeating a migration or scheduling a pod onto the wrong node; fix only what blocks the user-visible path."],
    's234-upgrade-through-pdb': ["The first drain refused because the budget allowed zero disruptions with three replicas. Relaxing it to minAvailable 2 let exactly one pod move at a time.", "The budget was kept, not deleted, so later maintenance stays protected.", "Order matters: control plane first, then one worker at a time, uncordoning each before touching the next.", "kubeadm upgrade apply runs on the control plane, kubeadm upgrade node on workers, and the kubelet only changes version once its package is installed and it is restarted."],
    's235-half-finished-upgrade': ["The kubelet on worker1 would not start because swap was on, so the new package never took effect after the restart.", "Recover the broken node before draining the healthy one, or the pods have nowhere to go.", "Read the kubelet log before changing anything: it named the cause.", "A half-finished upgrade is finished from the step it stopped at, not restarted from the top."],
    's236-selective-restore': ["Only the Deployment was missing, so only the Deployment needed restoring.", "kubectl create -f restores what is absent and reports AlreadyExists for the rest; kubectl apply -f would have put the old ConfigMap value back.", "A backup is a snapshot of last night: objects changed on purpose since then must not be rewound.", "Check what exists now before choosing the restore command."],
    's237-observability-evidence': ["With two containers in a pod you name the container for logs; the audit sidecar showed which path answered and which did not.", "Warning events and a crashed container's log disappear after a fix or a restart, so the evidence was saved first.", "The readiness probe stays: it keeps traffic away from pods that cannot answer. Only its path was wrong.", "A liveness probe restarts a stuck container; set its period and failure threshold so a slow moment does not trigger it."],
    's238-two-workers-four-rules': ["The DaemonSet skipped worker2 because its pods did not tolerate the taint, so a toleration was added and the taint stayed.", "A required anti-affinity of one pod per hostname caps the Deployment at the number of eligible nodes; two of four pods stayed Pending.", "A preferred rule still spreads pods when it can and does not block scheduling when it cannot.", "Taints put there on purpose are changed by their owner, not by whoever is blocked by them."],
    's239-add-context-then-work': ["A context is a cluster, user and namespace under one name; set-context created prod without touching the others.", "Switching context before each job, and checking current-context, keeps the right change in the right cluster.", "Nothing was edited with -n: the context carries the namespace.", "Ending on dev leaves the shell on the least dangerous context."]
  };
  Object.keys(d).forEach(function (k) { KL.debrief[k] = d[k]; });
})(typeof window !== 'undefined' ? window : globalThis);
